   const result:MaterialNode={id:uuid(),kind:'reference',title:'Moodboard · '+new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date()),image,originalImage:image,x:0,y:0,width:330,height:495,generated:true,trayOnly:true,trayOrder:Date.now(),resultType:'moodboard',sourceCount:sources.length};
   commit({...current,nodes:[result,...current.nodes]});setSelected([result.id]);setModal(null);setNotice('Moodboard готов: он добавлен первым слева в нижнюю ленту. Нажмите на него, чтобы открыть на весь экран.');
